<section class="admin-card"><div class="card-head"><div><h2>Product categories</h2><p>Control the category cards and product grouping on the public website.</p></div><a class="btn btn-primary" href="<?=e(url('admin/categories/add'))?>"><i class="fa-solid fa-plus"></i> Add Category</a></div><div class="table-responsive"><table class="admin-table"><thead><tr><th>Category</th><th>Products</th><th>Order</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><strong><?=e($category['name'])?></strong><small><?=e($category['slug'])?></small></td><td><?=number_format($category['product_count'])?></td><td><?=number_format($category['sort_order'])?></td><td><span class="status status-<?=strtolower($category['status'])?>"><?=e($category['status'])?></span></td><td><div class="table-actions"><a href="<?=e(url('admin/categories/'.$category['id'].'/edit'))?>"><i class="fa-solid fa-pen"></i></a><form method="post" action="<?=e(url('admin/categories/'.$category['id'].'/toggle'))?>"><?=csrf_field()?><button title="Toggle visibility"><i class="fa-solid fa-eye<?= $category['status']==='PUBLISHED'?'-slash':''?>"></i></button></form><form method="post" action="<?=e(url('admin/categories/'.$category['id'].'/delete'))?>" data-confirm="Delete this category? Categories containing products cannot be deleted."><?=csrf_field()?><button class="danger"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>

